""","""const DAY_MS = 24 * 60 * 60 * 1000;
const completedAt = new Date('2026-03-02T11:00:00Z');

describe('InvoicingService', () => {
  let repository: InMemoryInvoiceRepository;
  let clock: FixedClock;
  let service: InvoicingService;

  const encounter = (overrides: Partial<Parameters<InvoicingService['invoiceEncounter']>[0]> = {}) => ({
    encounterId: 'e-1',
    payerId: 'person-1',
    practitionerId: 'dr-house',
    procedureCodes: ['10101012'],
    completedAt,
    ...overrides,
  });

  beforeEach(() => {
