s=s.rstrip()
assert s.endswith("});")
s=s[:-3]+"""
  describe('follow-up within 30 days of a consultation', () => {
    async function firstConsultation(daysAgo: number, overrides = {}) {
      clock.set(new Date(completedAt.getTime() - daysAgo * DAY_MS));
      await service.invoiceEncounter(
        encounter({ encounterId: 'e-0', completedAt: clock.now(), procedureCodes: ['10101012'], ...overrides }),
      );
      clock.set(completedAt);
    }

    it('does not charge the consultation again but still charges other procedures', async () => {
      await firstConsultation(10);

      const invoice = await service.invoiceEncounter(encounter({ procedureCodes: ['10101012', '40304361'] }));

      expect(invoice?.toSnapshot().lines).toEqual([expect.objectContaining({ code: '40304361', amountCents: 3_500 })]);
    });

    it('issues no invoice when the consultation was the only procedure', async () => {
      await firstConsultation(10);

      await expect(service.invoiceEncounter(encounter())).resolves.toBeNull();
      expect(repository.items).toHaveLength(1);
    });

    it('charges the consultation on exactly the 30th day', async () => {
      await firstConsultation(30);

      const invoice = await service.invoiceEncounter(encounter({ procedureCodes: ['10101012', '40304361'] }));

      expect(invoice?.toSnapshot().lines.map((l) => l.code)).toEqual(['10101012', '40304361']);
    });

    it('charges the consultation again after the window has passed', async () => {
      await firstConsultation(31);

      const invoice = await service.invoiceEncounter(encounter());

      expect(invoice?.totalCents).toBe(25_000);
    });

    it('charges the consultation for a different practitioner', async () => {
      await firstConsultation(5);

      const invoice = await service.invoiceEncounter(encounter({ practitionerId: 'dr-wilson' }));

      expect(invoice?.totalCents).toBe(25_000);
    });

    it('charges the consultation for a different person', async () => {
      await firstConsultation(5);

      const invoice = await service.invoiceEncounter(encounter({ payerId: 'person-2' }));

      expect(invoice?.totalCents).toBe(25_000);
    });

    it('does not extend the window from a waived follow-up', async () => {
      await firstConsultation(31);
      await service.invoiceEncounter(encounter({ encounterId: 'e-1', procedureCodes: ['10101012', '40304361'] }));
      clock.set(new Date(completedAt.getTime() + 5 * DAY_MS));

      const invoice = await service.invoiceEncounter(
        encounter({ encounterId: 'e-2', completedAt: clock.now() }),
      );

      expect(invoice).toBeNull();
    });
  });
});
"""
open(p,'w').write(s)
EOF
